using System.Security.Claims;using System.Text;using CouponBook.Data.Entities;using Microsoft.Extensions.Options;using Microsoft.IdentityModel.JsonWebTokens;using Microsoft.IdentityModel.Tokens;
namespace CouponBook.Business.Auth;
public record AccessToken(string Value,int ExpiresInSeconds);
public interface ITokenService{AccessToken CreateAccessToken(User user,bool isProvider);}
public class TokenService:ITokenService{private readonly JwtOptions _o;private readonly JsonWebTokenHandler _h=new();public TokenService(IOptions<JwtOptions> o)=>_o=o.Value;public AccessToken CreateAccessToken(User u,bool isProvider){var life=TimeSpan.FromMinutes(_o.AccessTokenMinutes);var claims=new List<Claim>{new("sub",u.Id.ToString()),new("jti",Guid.NewGuid().ToString())};if(u.IsCustomer)claims.Add(new("role","Customer"));if(u.IsAdmin)claims.Add(new("role","Admin"));if(isProvider)claims.Add(new("role","Provider"));var d=new SecurityTokenDescriptor{Issuer=_o.Issuer,Audience=_o.Audience,Subject=new ClaimsIdentity(claims),Expires=DateTime.UtcNow.Add(life),SigningCredentials=new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(_o.SigningKey)),SecurityAlgorithms.HmacSha256)};return new(_h.CreateToken(d),(int)life.TotalSeconds);}}
